&\qquad\qquad\;
+\bigl(b^{2}\Delta y\bigr)^{2}
\bigl(\sigma_{y_{O1}}^{2}+\sigma_{y_{C7}}^{2}\bigr)
+\bigl(c^{2}\Delta z+a c\cos\beta\,\Delta x\bigr)^{2}
\bigl(\sigma_{z_{O1}}^{2}+\sigma_{z_{C7}}^{2}\bigr)
\Big\}\!,
\end{aligned}
}
